package com.reviewflow.service;
import com.reviewflow.domain.*;import com.reviewflow.integration.GoogleReviewProvider;import com.reviewflow.repo.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.time.*;
@Service public class SnapshotScheduler {private final BusinessRepository businesses;private final ReviewSnapshotRepository snapshots;private final GoogleReviewProvider google;public SnapshotScheduler(BusinessRepository b,ReviewSnapshotRepository s,GoogleReviewProvider g){businesses=b;snapshots=s;google=g;}@Scheduled(fixedDelayString="${app.sync-ms:43200000}")public void sync(){for(Business b:businesses.findAll()){try{var m=google.getBusinessMetrics(b);if(m.placeId()!=null&&!m.placeId().isBlank()){b.googlePlaceId=m.placeId();businesses.save(b);}ReviewSnapshot s=new ReviewSnapshot();s.businessId=b.id;s.snapshotDate=LocalDate.now();s.source="google_places";s.rating=m.rating();s.totalReviews=m.reviewCount();snapshots.save(s);}catch(Exception ignored){}}}}
